# SCHED_S_* 调度器信息码（0x41300~）——非故障，按语义呈现
_SCHED_INFO_CODES = {
    267008: ("就绪", "#8b949e"),      # SCHED_S_TASK_READY
    267009: ("运行中", "#d29922"),    # SCHED_S_TASK_RUNNING
    267010: ("未排程", "#8b949e"),    # SCHED_S_TASK_NOT_SCHEDULED
    267011: ("尚未运行", "#8b949e"),  # SCHED_S_TASK_HAS_NOT_RUN（新任务首跑前常态）
    267012: ("不再排程", "#8b949e"),  # SCHED_S_TASK_NO_MORE_RUNS
    267013: ("未终止", "#d29922"),    # SCHED_S_TASK_NOT_TERMINATED
    267014: ("无触发器", "#f85149"),  # SCHED_S_TASK_NO_VALID_TRIGGERS（真问题）
}


def _sched_rc_html(tstat):
    """计划任务状态串 → (显示文本, rc 判色 HTML)。

    267011 等信息码不是故障（新注册任务到点前 result 即 267011），
    误标红会把正常态当告警；last=11/30/1999 是 .NET DateTime.MinValue
    的本地化显示，规范为「尚未运行」。
    """
    if not tstat or tstat == "任务状态查询失败":
        return (tstat or "任务状态查询失败",
                "<b style='color:#8b949e'>状态未知</b>")
    if "not registered" in tstat:
        return tstat, "<b style='color:#8b949e'>未注册</b>"
    txt = tstat
    m = re.search(r"last=(\S+)(?:\s+(\S+))?", txt)
    _ym = re.search(r"(\d{4})", m.group(1)) if m else None
    if _ym and int(_ym.group(1)) < 2000:  # DateTime.MinValue 本地化假日期
        txt = txt[:m.start()] + "last=尚未运行" + txt[m.end():]
    m = re.search(r"result=(\d+)", txt)
    rc = int(m.group(1)) if m else None
    if rc == 0:
        return txt, "<b style='color:#3fb950'>正常</b>"
    if rc in _SCHED_INFO_CODES:
        label, color = _SCHED_INFO_CODES[rc]
        return txt, "<b style='color:%s'>%s</b>" % (color, label)
    return txt, ("<b style='color:#f85149'>rc=%s 异常</b>"
                 % (rc if rc is not None else "?"))


def _news_db():
    """news.db 轻量统计：今日采集/命中/已判分布 + 最近已判断条目。"""
    out = {"today": 0, "hit": 0, "dist": {"bull": 0, "bear": 0,
                                          "neutral": 0}, "recent": []}
    try:
        import sqlite3
        db = sqlite3.connect(os.path.join(STATION, "news_collector",
                                          "news.db"))
        out["today"] = db.execute(
            "SELECT COUNT(*) FROM news WHERE "
            "created_at>=date('now','localtime')").fetchone()[0]
        out["hit"] = db.execute(
            "SELECT COUNT(*) FROM news WHERE hit=1 AND "
            "created_at>=date('now','localtime')").fetchone()[0]
        for (j,) in db.execute(
                "SELECT jev FROM news WHERE jev IS NOT NULL AND "
                "created_at>=date('now','localtime')"):
            try:
                b = json.loads(j).get("bias", "neutral")
                out["dist"][b] = out["dist"].get(b, 0) + 1
            except Exception:
                log_exc("_news_db:jev 分布行解析")   # P0-5
        for ts, title, j in db.execute(
                "SELECT ts, title, jev FROM news WHERE jev IS NOT NULL "
                "ORDER BY id DESC LIMIT 12"):
            try:
                d = json.loads(j)
                out["recent"].append({"ts": ts, "title": title[:60],
                                      "bias": d.get("bias", "neutral"),
                                      "bias_cn": d.get("bias_cn", ""),
                                      "conf": d.get("conf", 0),
                                      "scope_cn": d.get("scope_cn", "")})
            except Exception:
                log_exc("_news_db:recent 行解析")  # C2批1
        db.close()
    except Exception:
        log_exc("_news_db:news.db 连接/统计")  # C2批1
    return out


def build_brief():
    """首页四板块卡的动态小字（轻量，直接读快照+news.db 计数）。"""
    pre = _read_json(os.path.join(REPORTS_DIR, "premarket_latest.json"))
    snap = _read_json(os.path.join(REPORTS_DIR, "rps_latest.json"))
    buy = [r for r in snap.get("res", [])
           if r.get("action") == "买入"]
    nw = _news_db()
    # G8 来源评级→门户红点：断流表数 / catalog 滞后在首页情报卡冒红/琥珀点
    # （纯文件读，与 /kg 折叠面板同一产物 kg_source_rating.json，单一数据源）
    rt = _read_json(os.path.join(QBT_DIR, "data",
                                 "kg_source_rating.json"))
    st = rt.get("staleness") or {}
    return {
        "ts": time.strftime("%Y-%m-%d %H:%M"),
        "fin": {"verdict": pre.get("verdict"), "prob": pre.get("prob"),
                "buy": len(buy), "latest": snap.get("latest", "")},
        "intel": {"today": nw["today"], "hit": nw["hit"], **nw["dist"]},
        "kg": {"stale": len(st.get("stale_tables") or []),
               "catalog_stale": bool(st.get("catalog_stale")),
               "catalog_age_days": st.get("catalog_age_days"),
               "ts": rt.get("ts")},
    }


