def _bt_resolve(q):
    """输入(名/代码/watchlist代码) → watchlist 条目；失败返回 None。"""
    import re as _re
    # ts_code 形态（000002.SZ/600519.SH/920088.BJ，KG 系页面跳转格式）
    # → 归一化小写两段式（sh600519）重解析，递归一层即止
    m = _re.fullmatch(r"(\d{6})\.(SH|SZ|BJ|sh|sz|bj)", str(q or "").strip())
    if m:
        return _bt_resolve("%s%s" % (m.group(2).lower(), m.group(1)))
    try:
        sys.path.insert(0, os.path.join(STATION, "news_collector"))
        import stock_analyze
        e = stock_analyze.resolve_stock(q)
        if e and e.get("name"):
            return e
    except Exception:
        pass
    # A股 RPS 榜形态（sh605177）：直接成条目，名称从快照 tops 反查
    if _re.fullmatch(r"[a-z]{2}\d{6}", q):
        nm = ""
        try:
            snap = json.load(open(os.path.join(
                STATION, "quant_backtest", "reports",
                "rps_latest.json"), encoding="utf-8"))
            for t in snap.get("tops", {}).get("CN", []):
                if t.get("sym") == "%s.%s" % (q[2:8], q[:2].upper()):
                    nm = t.get("name") or ""
                    break
        except Exception:
            pass
        if not nm:
            # K18-FIX：榜外票（不在 RPS tops）名称从图谱 Security 反查
            try:
                sys.path.insert(0, os.path.join(STATION, "quant_backtest"))
                import kg_portal as _KP
                r = _KP._q("MATCH (s:Security {ts_code:$tc}) "
                           "RETURN s.name AS nm LIMIT 1",
                           tc="%s.%s" % (q[2:8], q[:2].upper()))
                nm = ((r or [{}])[0] or {}).get("nm") or ""
            except Exception:
                pass
        return {"name": nm or q.upper(), "code": q, "aliases": []}
    try:
        wl = json.load(open(os.path.join(STATION, "news_collector",
                        "news_config.json"), encoding="utf-8"))["watchlist"]
    except Exception:
        return None
    for it in wl:
        if q in (it.get("code"), it.get("name")) or \
                q in (it.get("aliases") or []):
            return {"name": it.get("name") or q, "code": it.get("code", ""),
                    "aliases": it.get("aliases") or []}
    return None


def _bt_jev_news(name, aliases, hours=24 * 7):
    """近7天该标的关联的已判断新闻（news.jev）。"""
    import sqlite3
    from datetime import datetime as _dt, timedelta as _td
    since = (_dt.now() - _td(hours=hours)).strftime("%Y-%m-%d %H:%M")
    kws = {name} | {a for a in aliases if len(str(a)) >= 2}
    kws.discard("")
    out = []
    try:
        db = sqlite3.connect(os.path.join(STATION, "news_collector",
                                          "news.db"))
        rows = db.execute(
            "SELECT ts, title, jev FROM news WHERE jev IS NOT NULL "
            "AND created_at>=? ORDER BY id DESC LIMIT 3000",
            (since,)).fetchall()
        db.close()
    except Exception:
        log_exc("_bt_jev_news:news.db 查询")  # C2批1
        return out
    for ts, title, j in rows:
        if not title or not any(k in title for k in kws):
            continue
        try:
            jv = json.loads(j)
        except Exception:
            continue
        t = ts or ""
        if len(t) < 16 and t[:2].isdigit() and "-" in t[:6] \
                and not t.startswith("20"):
            # 部分新闻源 ts 无年份（如 "09-29 04:06"）：补当前年；
            # 跨年回看（拼出的日期在"未来"超1天）回退一年，保证
            # 时间轴比较与按日归组（/api/kline news 键）可用
            try:
                _p = _dt.strptime(t[:5], "%m-%d")
                _y = _dt.now().year
                if (_dt(_y, _p.month, _p.day) - _dt.now()).days > 1:
                    _y -= 1
                t = "%04d-%s" % (_y, t)
            except Exception:
                pass
        out.append({"ts": t[:16], "title": title,
                    "bias_cn": jv.get("bias_cn", "?"),
                    "conf": round((jv.get("conf") or 0) * 100),
                    "reason": jv.get("reason", "")})
        if len(out) >= 8:
            break
    return out


def _pool_bear_news(codes_names, days=5, min_conf=0.75, limit=12):
    """预警池利空消息警示（news.db 只读）：近 days 天 bias=bear 且
    置信≥min_conf、可归属到池内个股的消息。

    依据（llm观察记录 回测 v2）：偏空消息 T+1 跑输全市场 ~0.5pp，
    「避雷」方向有效 —— 只提示不拦截、不用于增强买入。
    归属三路：① stocks 列真 ts_code ② 标题前缀代码 [600853 龙建股份]
    / [个股研报·org] 300059 ③ 股票名出现在标题。
    返回 [{ts, code, name, title, conf, reason}]，新→旧。"""
    import sqlite3
    from datetime import datetime as _dt, timedelta as _td
    if not codes_names:
        return []
    since = (_dt.now() - _td(days=days)).strftime("%Y-%m-%d %H:%M")
    c6 = {c.split(".")[0]: c for c in codes_names}
    name2code = {n: c for c, n in codes_names.items() if n and len(n) >= 2}
    out, seen = [], set()
    try:
        db = sqlite3.connect(os.path.join(STATION, "news_collector",
                                          "news.db"))
        rows = db.execute(
            "SELECT created_at, title, stocks, jev FROM news "
            "WHERE jev IS NOT NULL AND created_at>=? "
            "ORDER BY id DESC LIMIT 4000", (since,)).fetchall()
        db.close()
    except Exception:
        log_exc("_pool_bear_news:news.db 查询")  # C2批1
        return out
    for ca, title, stocks, jev in rows:
        if not title:
            continue
        try:
            jv = json.loads(jev)
        except Exception:
            continue
        if jv.get("bias") != "bear" or (jv.get("conf") or 0) < min_conf:
            continue
        if jv.get("scope") != "cn":
            # 只取 A 股域消息：宏观/港股/商品域新闻按名归属噪声大
            # （实测：新世界发展≠新世界、金龙指数提及比亚迪、
            #  法国政局挂到金正大），警示层宁可漏报不可误报
            continue
        hit = None
        try:
            lst = json.loads(stocks) if stocks else []
        except Exception:
            lst = []
        for x in lst if isinstance(lst, list) else []:
            if isinstance(x, str) and x in codes_names:
                hit = x
                break
        if hit is None:
            m = re.match(r"^\[(\d{6})[\s·\]]", title)
            if not m:
                m = re.match(r"^\[[^\]]+\]\s*(\d{6})\s", title)
            if m and m.group(1) in c6:
                hit = c6[m.group(1)]
        if hit is None:
            for n, c in name2code.items():
                if n in title:
                    hit = c
                    break
        if hit is None:
            continue
        key = (hit, title[:40])
        if key in seen:
            continue
        seen.add(key)
        out.append({"ts": (ca or "")[:16], "code": hit,
                    "name": codes_names.get(hit, ""),
                    "title": title[:60],
                    "conf": round((jv.get("conf") or 0) * 100),
                    "reason": (jv.get("reason") or "")[:40]})
        if len(out) >= limit:
            break
    return out


_TS_DAILY_DF = None


def _ts_daily_prepend(ts_code, first_dt, need):
    """tdx ts_daily 取 first_dt 之前的收盘价尾部 need 根（MA 历史兜底）。

    返回 [(YYYYMMDD, close)...] 升序；全量 df 进程级缓存（首读 ~1.5s）。
    """
    global _TS_DAILY_DF
    try:
        import pandas as pd
        if _TS_DAILY_DF is None:
            import glob as _glob
            fs = sorted(_glob.glob(os.path.join(
                STATION, "quant_backtest", "data", "tdx", "ts_daily",
                "*.parquet")))
            _TS_DAILY_DF = pd.concat(
                [pd.read_parquet(f, columns=["ts_code", "trade_date",
                                              "close"]) for f in fs],
                ignore_index=True)
        fd = first_dt.strftime("%Y%m%d")
        d = _TS_DAILY_DF[_TS_DAILY_DF["ts_code"] == ts_code]
        d = d[d["trade_date"].astype(str) < fd].sort_values("trade_date")
        d = d.tail(need)
        return list(zip(d["trade_date"].astype(str),
                        d["close"].astype(float)))
    except Exception:
        return []


def _kline_data(q, n=250):
    """个股 K 线（S1）：四市场日线尾部 n 根 + MA5/20/60/250 + A股图谱结构
    信号标注 + JEV 新闻 bias 标注。resolve → load_bars，纯查询。"""
    n = max(30, min(500, int(n or 250)))
    e = _bt_resolve(q)
    if not e:
        return {"ok": False, "err": "未识别「%s」" % q}
    name, code = e["name"], e.get("code", "")
    aliases = e.get("aliases") or []
    # A股 ts_code（结构信号标注与 MA 历史兜底共用）
    import re as _re_k
    m6 = _re_k.search(r"(\d{6})", code or "")
    ts_code = ""
    if m6:
        d6 = m6.group(1)
        ts_code = (d6 + ".SH" if d6[0] == "6" else d6 + ".SZ"
                   if d6[0] in "03" else d6 + ".BJ" if d6[0] in "48" else "")
    bars = []
    try:
        from datetime import datetime as _dt, timedelta as _td
        sys.path.insert(0, os.path.join(STATION, "quant_backtest"))
        import runner as _R
        import data_loader as _D
        # MA250 需视图外 ≥250 根历史：窗口 ≈ 视图 1.6 倍 + 420 自然日
        start = (_dt.now() - _td(days=int(n * 1.6) + 420)
                 ).strftime("%Y-%m-%d")
        for mk, sy, _nm in _R.resolve_watchlist(
                [{"name": name, "code": code, "aliases": aliases}]):
            df = _D.load_bars(mk, [sy], start, None).get(sy)
            if df is not None and len(df):
                # K152 排序强保证：parquet 原序不可控，统一按日期升序
                # （日/周/月三级别与 MA/MACD 全链路的顺序根基）
                bars = df.sort_index()
                break
    except Exception:
        log_exc("_kline_data:load_bars 日线加载 %s/%s" % (name, code))  # C2批1
        bars = []
    if bars is None or not len(bars):
        return {"ok": False, "err": "无日线数据（%s · %s）" % (name, code)}
    # MA 先全量算（保证切尾后头部均线完整），再取尾部 n 根。
    # 本地日线池短于 250+n 根时（ashare 池 2025-02 起），用 tdx ts_daily
    # 收盘价向前补（两源同口径不复权，实测逐日一致）
    closes = list(bars["close"])
    pre = []
    if ts_code and len(closes) - n < 250:
        pre = _ts_daily_prepend(ts_code, bars.index[0], 300)
        if pre:
            closes = [c for _dd, c in pre] + closes
    mas = {k: [None] * len(closes) for k in (5, 20, 60, 250)}
    for k in (5, 20, 60, 250):
        s = 0.0
        for i, c in enumerate(closes):
            s += c
            if i >= k:
                s -= closes[i - k]
            if i >= k - 1:
                mas[k][i] = round(s / k, 3)
    off = len(pre)
    out = []
    idxs = list(bars.index)
    for j, i in enumerate(idxs):
        out.append({"d": i.strftime("%Y-%m-%d"),
                    "o": round(float(bars.at[i, "open"]), 3),
                    "h": round(float(bars.at[i, "high"]), 3),
                    "l": round(float(bars.at[i, "low"]), 3),
                    "c": round(float(bars.at[i, "close"]), 3),
                    "v": float(bars.at[i, "volume"] or 0),
                    "m5": mas[5][j + off], "m20": mas[20][j + off],
                    "m60": mas[60][j + off], "m250": mas[250][j + off]})
    out = out[-n:]
    # A股：图谱结构信号标注（缠论买卖点，kg_portal 纯查询）
    marks = []
    if ts_code:
        try:
            import kg_portal as _KP
            st = _KP.stock(ts_code, days=n)
            for s in (st.get("structures") or [])[:40]:
                marks.append({"d": s.get("date") or "",
                              "t": s.get("type") or "",
                              "c": round(s.get("conf") or 0, 2)})
        except Exception:
            pass
    # JEV 新闻 bias 标注（按日期去重，同日多条取 conf 最高）
    news = {}
    for it in _bt_jev_news(name, aliases):
        d = (it.get("ts") or "")[:10]
        if d and (d not in news or it["conf"] > news[d]["c"]):
            news[d] = {"c": it["conf"], "b": it["bias_cn"]}
    # K136 笔中枢上墙：全量窗 P3 结构（chanlun_bi，四市场纯几何，
    # 不限 A股）；dt=原始 K 线日期，前端按视窗类目自动过滤
    # K139 周线级别：ISO 周一 groupby 重采样，dt=周内最后交易日
    # （与前端 _wk() 的 w.d 口径对齐），analyze 出 wbis/wpivots
    bis, pivots, wbis, wpivots = [], [], [], []
    mbis, mpivots, fx, wfx, mfx = [], [], [], [], []
    sgs, wsgs, msgs = [], [], []
    sigs, wsigs, msigs = [], [], []
    try:
        import pandas as pd
        from chanlun_bi import analyze as _cl3
        cl = _cl3([{"dt": i.strftime("%Y-%m-%d"),
                    "h": float(bars.at[i, "high"]),
                    "l": float(bars.at[i, "low"])}
                   for i in bars.index],
                  [float(bars.at[i, "close"]) for i in bars.index])
        # K141 笔段挂 d(dir 方向)/pp(涨跌幅%)，中枢挂 n(段数)
        bis = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                "ep": b["e_price"], "d": b.get("dir", 0),
                "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                if b["s_price"] else 0} for b in cl["bis"]]
        pivots = [{"s": p["s_dt"], "e": p["e_dt"], "zg": p["zg"],
                   "zd": p["zd"], "n": p.get("n_bi", 0)}
                  for p in cl["pivots"]]
        # K142 分型标注：P2 全量分型（顶/底），t=1 顶 / -1 底
        fx = [{"d": f["dt"], "p": f["price"],
               "t": 1 if f["type"] == "顶" else -1}
              for f in cl["fractals"]]
        # K149 线段上墙：破坏确认法段（nb=段内笔数）
        sgs = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                "ep": b["e_price"], "d": b.get("dir", 0),
                "nb": b.get("n_bi", 0),
                "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                if b["s_price"] else 0} for b in cl["segments"]]
        # K151 三类买卖点（引擎简化判据）透传；K154 sub 子类（1 类：
        # tbe 趋势背驰/pbe 盘整背驰，标注不拦截）
        sigs = [{"d": g["d"], "p": g["p"], "t": g["t"],
                 "sub": g.get("sub", "")}
                for g in cl["signals"]]
        keys = [i - pd.Timedelta(days=i.dayofweek) for i in bars.index]
        g = bars.groupby(keys)
        wdf = pd.DataFrame({"d": g.apply(lambda x: x.index[-1]),
                            "h": g["high"].max(), "l": g["low"].min(),
                            "c": g["close"].last()})
        cw = _cl3([{"dt": r["d"].strftime("%Y-%m-%d"),
                    "h": float(r["h"]), "l": float(r["l"])}
                   for _, r in wdf.iterrows()],
                  [float(r["c"]) for _, r in wdf.iterrows()])
        wbis = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                 "ep": b["e_price"], "d": b.get("dir", 0),
                 "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                 if b["s_price"] else 0} for b in cw["bis"]]
        wpivots = [{"s": p["s_dt"], "e": p["e_dt"], "zg": p["zg"],
                    "zd": p["zd"], "n": p.get("n_bi", 0)}
                   for p in cw["pivots"]]
        wfx = [{"d": f["dt"], "p": f["price"],
                "t": 1 if f["type"] == "顶" else -1}
               for f in cw["fractals"]]
        wsgs = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                 "ep": b["e_price"], "d": b.get("dir", 0),
                 "nb": b.get("n_bi", 0),
                 "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                 if b["s_price"] else 0} for b in cw["segments"]]
        wsigs = [{"d": g["d"], "p": g["p"], "t": g["t"],
                  "sub": g.get("sub", "")}
                 for g in cw["signals"]]
        # K140 月线级别：Period(M) 标量键 groupby（元组键会被 pandas
        # 当多列 key 误解析），dt=月内最后交易日（同周口径）
        gm = bars.groupby([i.to_period("M") for i in bars.index])
        mdf = pd.DataFrame({"d": gm.apply(lambda x: x.index[-1]),
                            "h": gm["high"].max(), "l": gm["low"].min(),
                            "c": gm["close"].last()})
        cmm = _cl3([{"dt": r["d"].strftime("%Y-%m-%d"),
                     "h": float(r["h"]), "l": float(r["l"])}
                    for _, r in mdf.iterrows()],
                   [float(r["c"]) for _, r in mdf.iterrows()])
        mbis = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                 "ep": b["e_price"], "d": b.get("dir", 0),
                 "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                 if b["s_price"] else 0} for b in cmm["bis"]]
        mpivots = [{"s": p["s_dt"], "e": p["e_dt"], "zg": p["zg"],
                    "zd": p["zd"], "n": p.get("n_bi", 0)}
                   for p in cmm["pivots"]]
        mfx = [{"d": f["dt"], "p": f["price"],
                "t": 1 if f["type"] == "顶" else -1}
               for f in cmm["fractals"]]
        msgs = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                 "ep": b["e_price"], "d": b.get("dir", 0),
                 "nb": b.get("n_bi", 0),
                 "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                 if b["s_price"] else 0} for b in cmm["segments"]]
        msigs = [{"d": g["d"], "p": g["p"], "t": g["t"],
                  "sub": g.get("sub", "")}
                 for g in cmm["signals"]]
    except Exception:
        log_exc("_kline_data:缠论多级别结构")  # C2批1
    # K172 P2 15 形态识别 + 信号日共振映射（四市场纯 OHLC 规则，
    # chanlun_pattern 自研引擎；ptmap 仅含结构信号日出现的形态）
    pats, ptmap = [], {}
    try:
        from chanlun_pattern import detect as _pdt, resonmap as _pres
        pbars = [{"dt": x["d"], "o": x["o"], "h": x["h"],
                  "l": x["l"], "c": x["c"]} for x in out]
        pats = _pdt(pbars)
        ptmap = _pres(pats, [g["d"] for g in sigs])
    except Exception:
        log_exc("_kline_data:chanlun_pattern 形态识别")  # C2批1
    return {"ok": True, "name": name, "code": code,
            "bars": out, "marks": marks, "news": news,
            "bis": bis, "pivots": pivots,
            "wbis": wbis, "wpivots": wpivots,
            "mbis": mbis, "mpivots": mpivots,
            "fx": fx, "wfx": wfx, "mfx": mfx,
            "sgs": sgs, "wsgs": wsgs, "msgs": msgs,
            "sigs": sigs, "wsigs": wsigs, "msigs": msigs,
            "patterns": pats, "ptmap": ptmap}


def _kline_qy(c):
    """个股季/年线 JSON（K200：K147-F 季/年线级别落地）。

    深历史：datamart daily 别名 = ts_daily（xtcloud 2023-07 起）+
    tushare 深历史 daily（by_date，1990 起，freshness 20230728）；
    按请求区间降级——end≤20230730 命中深表（实测单票 0.6s/2925 行），
    start≥20230731 命中 ts_daily。两段拼接 (code,date) 去重。
    服务端聚合季/年 OHLCV + MA + chanlun_bi 结构；仅 A 股（深源为
    tushare CN）。懒加载独立端点，默认 /api/kline 零改动零回归。"""
    e = _bt_resolve(c)
    if not e:
        return {"ok": False, "err": "未识别「%s」" % c}
    code = e.get("code", "")
    m6 = re.search(r"(\d{6})", code or "")
    if not m6:
        return {"ok": False, "err": "季/年线仅支持 A 股（深历史源为 CN）"}
    d6 = m6.group(1)
    ts_code = (d6 + ".SH" if d6[0] == "6" else d6 + ".SZ"
               if d6[0] in "03" else d6 + ".BJ" if d6[0] in "48" else "")
    if not ts_code:
        return {"ok": False, "err": "季/年线仅支持 A 股（北交所 %s 无深历史"
                                     "确认）" % d6}
    try:
        sys.path.insert(0, os.path.join(STATION, "quant_backtest"))
        import datamart as _dm
        d1 = _dm.read("daily", codes=[ts_code], start="19900101",
                      end="20230730")
        d2 = _dm.read("daily", codes=[ts_code], start="20230731")
    except Exception as ex:
        return {"ok": False, "err": "深历史读取失败 %s" % str(ex)[:80]}
    import pandas as _pd
    df = _pd.concat([x for x in (d1, d2) if x is not None and len(x)] ,
                    ignore_index=True)
    if df is None or not len(df):
        return {"ok": False, "err": "%s 无日线深历史" % ts_code}
    df = df.drop_duplicates("trade_date").sort_values("trade_date") \
        .reset_index(drop=True)
    if "close" not in df.columns or len(df) < 12:
        return {"ok": False, "err": "深历史不足（%d 根）" % len(df)}
    td = df["trade_date"].astype(str)
    dts = td.str.slice(0, 4) + "-" + td.str.slice(4, 6) + "-" + \
        td.str.slice(6, 8)

    def _agg(freq):
        if freq == "q":
            key = dts.str.slice(0, 4) + "Q" + (
                (dts.str.slice(5, 7).astype(int) - 1) // 3 + 1).astype(str)
        else:
            key = dts.str.slice(0, 4)
        g = df.assign(_k=key).groupby("_k", sort=True)
        out = []
        for k, x in g:
            out.append({"d": dts.iloc[x.index[-1]],
                        "w0": dts.iloc[x.index[0]],
                        "o": round(float(x["open"].iloc[0]), 2),
                        "h": round(float(x["high"].max()), 2),
                        "l": round(float(x["low"].min()), 2),
                        "c": round(float(x["close"].iloc[-1]), 2),
                        "v": float(x["volume"].sum()) if "volume"
                        in x.columns else 0.0})
        for kk in (5, 20, 60, 250):
            vals = [b["c"] for b in out]
            for i, b in enumerate(out):
                b["m%d" % kk] = (round(sum(vals[i - kk + 1:i + 1]) / kk, 3)
                                 if i >= kk - 1 else None)
        from chanlun_bi import analyze as _clq
        cl = _clq([{"dt": b["d"], "h": b["h"], "l": b["l"]} for b in out],
                  [b["c"] for b in out])
        bis = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                "ep": b["e_price"], "d": b.get("dir", 0),
                "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                if b["s_price"] else 0} for b in cl["bis"]]
        pivots = [{"s": p["s_dt"], "e": p["e_dt"], "zg": p["zg"],
                   "zd": p["zd"], "n": p.get("n_bi", 0)}
                  for p in cl["pivots"]]
        fxl = [{"d": f["dt"], "p": f["price"],
                "t": 1 if f["type"] == "顶" else -1}
               for f in cl["fractals"]]
        sgs = [{"s": b["s_dt"], "e": b["e_dt"], "sp": b["s_price"],
                "ep": b["e_price"], "d": b.get("dir", 0),
                "nb": b.get("n_bi", 0),
                "pp": round((b["e_price"] / b["s_price"] - 1) * 100, 1)
                if b["s_price"] else 0} for b in cl["segments"]]
        sigs = [{"d": g2["d"], "p": g2["p"], "t": g2["t"],
                 "sub": g2.get("sub", "")} for g2 in cl["signals"]]
        return {"bars": out, "bis": bis, "pivots": pivots, "fx": fxl,
                "sgs": sgs, "sigs": sigs, "marks": [], "news": {}}

    try:
        q = _agg("q")
        y = _agg("y")
    except Exception as ex:
        return {"ok": False, "err": "季/年结构计算失败 %s" % str(ex)[:80]}
    return {"ok": True, "name": e["name"], "code": code,
            "q": q, "y": y,
            "deep_span": "%s..%s" % (dts.iloc[0], dts.iloc[-1]),
            "n_deep": int(len(df))}


_CHIPS_FLOCK = threading.Lock()


# ── K239 个股所属板块联动（tdx 板块定义/成分 + 板块指数涨跌） ──
_SEC_CACHE = {"ts": 0.0, "rev": None, "rps": None, "daily": None}


def _stock_sector_rows(code, limit=4):
    """个股 → 所属板块行（K239 板块联动）：[{sector, idx, chg1, chg5,
    rps50}...]，按 RPS50 降序取前 limit。

    数据源（全部进程缓存 1 小时）：
      tdx_sector_def（板块定义，排除 stat/region）+ tdx_sector_member
      （成分，con_code=6 位纯码）→ 个股倒排；
      reports/sector_effect.json → 板块 RPS50；
      tdx_sector_daily → 板块指数当日/5 日涨跌。
    异常/无数据返回 []（页面安全降级，不阻塞个股页）。"""
    import time as _t_sec
    m6 = "".join(ch for ch in str(code or "") if ch.isdigit())[-6:]
    if len(m6) != 6:
        return []
    now = _t_sec.time()
    try:
        if _SEC_CACHE["rev"] is None or now - _SEC_CACHE["ts"] > 3600:
            import pandas as _pd_sec
            import glob as _glob_sec
            tdx = os.path.join(STATION, "quant_backtest", "data", "tdx")

            def _rp(tbl, cols=None):
                parts = sorted(_glob_sec.glob(
                    os.path.join(tdx, tbl, "part_*.parquet")))
                if not parts:
                    return _pd_sec.DataFrame()
                return _pd_sec.concat(
                    [_pd_sec.read_parquet(p, columns=cols) for p in parts],
                    ignore_index=True)

            seg = _rp("tdx_sector_def", ["code", "name", "seg"])
            seg = seg[~seg["seg"].isin({"stat", "region"})] \
                if len(seg) else seg
            name2idx = {str(n): str(c) for c, n in
                        zip(seg["code"], seg["name"])} if len(seg) else {}
            mem = _rp("tdx_sector_member", ["block_name", "con_code"])
            rev = {}
            if len(mem):
                for b, cc in zip(mem["block_name"], mem["con_code"]):
                    ic = name2idx.get(str(b))
                    if not ic:
                        continue          # 只认有指数的板块（881 行业等）
                    rev.setdefault(str(cc).zfill(6), []).append(
                        (str(b), ic))
            eff = _read_json(os.path.join(STATION, "quant_backtest",
                                          "reports",
                                          "sector_effect.json")) or {}
            rps = {s.get("sector"): s.get("rps50")
                   for s in (eff.get("sectors") or []) if s.get("sector")}
            daily = _rp("tdx_sector_daily",
                        ["code", "trade_date", "close"])
            _SEC_CACHE.update({"rev": rev, "rps": rps,
                               "daily": daily if len(daily) else None,
                               "ts": now})
        rev, rps, daily = (_SEC_CACHE["rev"], _SEC_CACHE["rps"],
                           _SEC_CACHE["daily"])
        hits = (rev or {}).get(m6) or []
        if not hits:
            return []
        rows = []
        for bname, ic in hits:
            chg1 = chg5 = None
            if daily is not None:
                sub = daily[daily["code"].astype(str) == str(ic)]
                if len(sub) >= 2:
                    sub = sub.sort_values("trade_date")
                    cl = sub["close"].astype(float).tolist()
                    if cl[-1]:
                        chg1 = (cl[-1] / cl[-2] - 1) * 100 if cl[-2] else None
                        chg5 = ((cl[-1] / cl[-6] - 1) * 100
                                if len(cl) >= 6 and cl[-6] else None)
            rows.append({"sector": bname, "idx": ic, "chg1": chg1,
                         "chg5": chg5, "rps50": rps.get(bname)})
        rows = [r for r in rows
                if r["chg1"] is not None or r["rps50"] is not None]
        rows.sort(key=lambda r: (r["rps50"] if r["rps50"] is not None
                                 else -1), reverse=True)
        return rows[:limit]
    except Exception:
        return []


def _stock_chip_summary(code, px):
    """个股筹码摘要（K239 结论卡用）：只读本地 cyq_chips parquet 最新
    交易日（不在线拉，避免页首阻塞），avg=筹码加权均成本，
    winner=现价下方筹码占比。返回 {d, avg, winner, pos} 或 None。"""
    import re as _re_chip
    m6 = _re_chip.search(r"(\d{6})", str(code or ""))
    if not m6:
        return None
    d6 = m6.group(1)
    ts_code = (d6 + ".SH" if d6[0] == "6" else d6 + ".SZ"
               if d6[0] in "03" else d6 + ".BJ" if d6[0] in "48" else "")
    if not ts_code:
        return None
    cfile = os.path.join(STATION, "quant_backtest", "data", "tushare",
                         "cyq_chips", ts_code.replace(".", "_") + ".parquet")
    try:
        import pandas as _pd_chip
        if not os.path.exists(cfile):
            return None
        df = _pd_chip.read_parquet(cfile)
        if df is None or not len(df):
            return None
        last = str(df["trade_date"].max())
        rows = df[df["trade_date"].astype(str) == last]
        pr = [(float(p), float(pc)) for p, pc in
              zip(rows["price"], rows["percent"]) if float(p) > 0]
        if not pr:
            return None
        avg = round(sum(p * pc for p, pc in pr) / 100.0, 2)
        winner = pos = None
        try:
            close = round(float(px), 2)
        except (TypeError, ValueError):
            close = None
        if close:
            winner = round(sum(pc for p, pc in pr if p <= close), 1)
            pos = round((close / avg - 1) * 100, 1) if avg else None
        return {"d": "%s-%s-%s" % (last[:4], last[4:6], last[6:8]),
                "avg": avg, "winner": winner, "pos": pos}
    except Exception:
        return None


def _chips_data(q, d, x=None):
    """个股筹码分布瀑布（S5）：cyq_chips 单日按需 + parquet 缓存。

    A股专属；x=当日收盘价（计算获利盘/平均成本，仅展示用途）。
    返回按价升序 rows=[[price,percent]...]（已滤 price<=0 垃圾行）。
    """
    import re as _re
    m6 = _re.search(r"(\d{6})", str(q or ""))
    ts_code = ""
    if m6:
        d6 = m6.group(1)
        ts_code = (d6 + ".SH" if d6[0] == "6" else d6 + ".SZ"
                   if d6[0] in "03" else d6 + ".BJ" if d6[0] in "48" else "")
    if not ts_code:
        return {"ok": False, "err": "筹码分布为 A 股专属"}
    dd = _re.sub(r"\D", "", str(d or ""))[:8]
    if len(dd) != 8:
        return {"ok": False, "err": "日期无效"}
    cdir = os.path.join(STATION, "quant_backtest", "data",
                        "tushare", "cyq_chips")
    cfile = os.path.join(cdir, ts_code.replace(".", "_") + ".parquet")
    rows = None
    try:
        import pandas as pd
        df = pd.read_parquet(cfile) if os.path.exists(cfile) else None
        if df is not None and len(df) and (df["trade_date"] == dd).any():
            rows = df[df["trade_date"] == dd]
        else:
            with _CHIPS_FLOCK:  # 在线拉取+落盘串行化（单用户门户足够）
                df2 = pd.read_parquet(cfile) if os.path.exists(cfile) else None
                if df2 is not None and len(df2) and \
                        (df2["trade_date"] == dd).any():
                    rows = df2[df2["trade_date"] == dd]  # 双检：等锁期间已被拉过
                else:
                    # 区间拉取（45天）：休市幻影K线回退最近交易日，
                    # 顺带预热缓存供 dataZoom 回滚复用
                    import datetime as _dt
                    d0 = _dt.datetime.strptime(dd, "%Y%m%d") - \
                        _dt.timedelta(days=45)
                    sys.path.insert(0, os.path.join(STATION,
                                                    "quant_backtest"))
                    import tushare_sync as _TS
                    data = _TS.ts_call("cyq_chips", {
                        "ts_code": ts_code,
                        "start_date": d0.strftime("%Y%m%d"),
                        "end_date": dd})
                    fields = data.get("fields") or []
                    fi = {f: i for i, f in enumerate(fields)}
                    ndf = pd.DataFrame(
                        [[str(r[fi["trade_date"]]), float(r[fi["price"]]),
                          float(r[fi["percent"]])]
                         for r in (data.get("items") or [])
                         if r[fi["price"]] is not None
                         and float(r[fi["price"]]) > 0],
                        columns=["trade_date", "price", "percent"])
                    base = df2 if df2 is not None else df
                    merged = pd.concat([t for t in (base, ndf)
                                        if t is not None and len(t)])
                    if len(merged):
                        merged = merged[merged["trade_date"].astype(str)
                                        <= dd]
                    if not len(merged):
                        return {"ok": False,
                                "err": "该日无筹码数据（%s）" % dd}
                    merged = merged.drop_duplicates(
                        ["trade_date", "price"]).sort_values(
                        ["trade_date", "price"])
                    os.makedirs(cdir, exist_ok=True)
                    merged.to_parquet(cfile, index=False)
                    last = str(merged["trade_date"].max())
                    rows = merged[merged["trade_date"].astype(str) == last]
                    dd = last  # 实际取到的交易日
        rr = sorted((round(float(p), 2), round(float(pc), 3))
                    for p, pc in zip(rows["price"], rows["percent"]))
        try:
            close = round(float(x), 2)
        except (TypeError, ValueError):
            close = None
        winner = avg = None
        if close and rr:
            winner = round(sum(pc for p, pc in rr if p <= close), 1)
            avg = round(sum(p * pc for p, pc in rr) / 100.0, 2)
        return {"ok": True, "code": ts_code,
                "d": "%s-%s-%s" % (dd[:4], dd[4:6], dd[6:8]),
                "close": close,
                "winner": winner, "avg": avg, "rows": rr}
    except Exception as ex:
        return {"ok": False, "err": "筹码获取失败：%s" % str(ex)[:120]}


def _sa_worker(jid, q):
    try:
        sys.path.insert(0, os.path.join(STATION, "news_collector"))
        import stock_analyze
        d = stock_analyze.analyze_detail(q)
        d["card"] = False
        if d.get("ok"):  # SYSTEM 上下文无 lark-cli 凭证：入队，由
            # 「AI个股分析轮询」任务(Administrator)每 5 分钟代推飞书卡
            try:
                rec = {k: d.get(k) for k in (
                    "name", "bias", "strength", "news_n", "px", "stat",
                    "outlook", "judged")}
                with open(os.path.join(STATION, "news_collector",
                                       "sa_push_queue.jsonl"), "a",
                          encoding="utf-8") as f:
                    f.write(json.dumps(rec, ensure_ascii=False) + "\n")
                d["card"] = "queued"
            except OSError:
                pass
        SA_JOBS[jid] = {"status": "done", "d": d}
        if d.get("ok"):
            _sa_hist_append(d)
    except Exception as ex:
        import traceback
        SA_JOBS[jid] = {"status": "done",
                        "d": {"ok": False, "msg": "分析异常：%s" % str(ex)[:200]}}
        try:  # 线程内异常落盘，便于排查门户任务上下文问题
            with open(os.path.join(STATION, "news_collector",
                                   "sa_page_error.log"), "a",
                      encoding="utf-8") as f:
                f.write("[%s] %s\n" % (q, traceback.format_exc()))
        except OSError:
            pass
    finally:
        SA_BUSY["v"] = False


def _matrix_cards(cross_data, cross_hit, sig_states, sig_err, items):
    """个股全景页「方法论矩阵」卡片组（纯函数：数据进 → 卡片 HTML 列表出）。

    A 段：遍历 cross_poll.STRATEGIES 注册表逐策略出卡——命中显示
    label+方向色（long→buy / short→avoid / neutral→watch），未命中
    mute 半透明；新增策略只改 cross_poll.STRATEGIES，本函数零改。
    B 段：本地附加卡（实时 4 策略持仓 → 锚点④ / JEV → ⑤ / AI → ⑥），
    不属于 cross 聚合口径，故不进注册表。

    参数：cross_data=build_cross() 聚合结果（含 strategies 注册表镜像）、
    cross_hit=该票在 stocks[] 的条目或 None、sig_states={sn: 多头|空头|
    空仓}、sig_err=实时计算失败原因、items=JEV 已判断新闻列表。
    """
    import html as _h
    e = _h.escape
    mcards = []
    _dir_cls = {"long": "buy", "short": "avoid", "neutral": "watch"}
    hits_by_sid = {h["sid"]: h for h in (cross_hit or {}).get("hits", [])}
    for s in cross_data.get("strategies", []):
        hit = hits_by_sid.get(s["id"])
        icon = s.get("icon") or "🧪"
        if hit:
            extra = (e(str(hit["dt"])) + " · " if hit.get("dt") else "")
            mcards.append(
                "<a class='mcard' href='%s'>"
                "<div class='mt'>%s %s</div>"
                "<div class='mv %s'>%s</div>"
                "<div class='mu'>%s→ 工作台</div></a>"
                % (s["url"], icon, e(str(s["name"])),
                   _dir_cls.get(hit["dir"], ""), e(str(hit["label"])),
                   extra))
        else:
            mcards.append(
                "<a class='mcard mute' href='%s'>"
                "<div class='mt'>%s %s</div>"
                "<div class='mv'>未命中</div>"
                "<div class='mu'>→ 工作台</div></a>"
                % (s["url"], icon, e(str(s["name"]))))
    # B1. 4 策略实时持仓（实时计算，比快照口径更细 → 锚点 ④）
    if sig_states:
        _nl = sum(1 for v in sig_states.values() if v == "多头")
        _cls = "buy" if _nl >= 3 else ("avoid" if _nl == 0 else "")
        mcards.append(
            "<a class='mcard' href='#sig4'>"
            "<div class='mt'>📈 实时持仓 · 4策略</div>"
            "<div class='mv %s'>%d/4 多头</div>"
            "<div class='mu'>↓ 见下文 ④</div></a>" % (_cls, _nl))
    else:
        mcards.append(
            "<a class='mcard mute' href='#sig4'>"
            "<div class='mt'>📈 实时持仓 · 4策略</div>"
            "<div class='mv'>%s</div>"
            "<div class='mu'>↓ 见下文 ④</div></a>" % (sig_err or "—"))
    # B2. JEV 消息面（→ 锚点 ⑤）
    if items:
        _n_bull = sum(1 for it in items if it["bias_cn"] == "利多")
        _n_bear = sum(1 for it in items if it["bias_cn"] == "利空")
        _dom = ("利多" if _n_bull > _n_bear else
                "利空" if _n_bear > _n_bull else "分歧")
        _cls = ("buy" if _dom == "利多" else
                "avoid" if _dom == "利空" else "watch")
        mcards.append(
            "<a class='mcard' href='#jev'>"
            "<div class='mt'>⚖️ JEV 消息面</div>"
            "<div class='mv %s'>%s · %d 条</div>"
            "<div class='mu'>↓ 见下文 ⑤</div></a>"
            % (_cls, _dom, len(items)))
    else:
        mcards.append(
            "<a class='mcard mute' href='/bt-jev'>"
            "<div class='mt'>⚖️ JEV 消息面</div>"
            "<div class='mv'>近7天无判断</div>"
            "<div class='mu'>→ JEV 主页</div></a>")
    # B3. AI 深度分析（→ 锚点 ⑥）
    mcards.append(
        "<a class='mcard' href='#ai'>"
        "<div class='mt'>🤖 AI 深度分析</div>"
        "<div class='mv'>即时跑 · 2-4 分钟</div>"
        "<div class='mu'>↓ 见下文 ⑥</div></a>")
    return mcards


